import logging
from pathlib import Path
from typing import Union

from taf.transport.ssh import ssh


class AirphoneLogsCollector:
    def __init__(self, airphone_details: dict):
        self.airphone_script = self._get_airphone_script_path(airphone_details)
        self.script_timeout = airphone_details.get("timeout", 1800)
        self.airphone_vm = self._get_airphone_vm_details(airphone_details)
        self.airphone_script_dir = self.airphone_script.rsplit("/", 1)[0]
        self.airphone_connection = self.AirphoneSshContextManager(self.airphone_vm)

    class AirphoneSshContextManager(ssh):
        def __init__(self, airphone_vm: dict):
            super().__init__()
            self.airphone_vm = airphone_vm
            self.ssh_client: ssh = None
            self.connection = None

        def __enter__(self):
            self.ssh_client = ssh()
            logging.debug("Connecting to AirPhone VM")
            self.connection = self.ssh_client.connect_to(**self.airphone_vm)
            return self

        def __exit__(self, exc_type, exc_val, exc_tb):
            logging.debug(f"Closing AirPhone VM connection")
            self.ssh_client.disconnect(connection=self.connection)

    def collect_snapshot(self, target_dir: str):
        with self.airphone_connection as airphone_connection:
            try:
                target_path = Path(target_dir)
                target_path.mkdir(exist_ok=True)
                logging.debug(f"Executing chmod 755 {self.airphone_script}")
                airphone_connection.execute(f"chmod 755 {self.airphone_script}")
                logging.debug(f"Executing script: {self.airphone_script}")
                output_file = "airphone_script_output.log"
                airphone_connection.execute(f"cd {self.airphone_script_dir}; "
                                            f"source {self.airphone_script} > {output_file}",
                                            timeout=self.script_timeout)
                logging.debug(f"List all files from {self.airphone_script_dir}")
                all_files = airphone_connection.execute(f"ls -A1 {self.airphone_script_dir}").rstrip()
                logging.debug(f"Listed files: \n{all_files}")
                files_from_target_dir = [f'{self.airphone_script_dir}/{log_file.rstrip()}'
                                         for log_file in all_files.split("\n") if log_file.rstrip().endswith('.tgz')]
                files_from_target_dir.append(f"{self.airphone_script_dir}/{output_file}")
                logging.debug(f"Downloading files: {files_from_target_dir} to {target_dir}")
                airphone_connection.download_file(files_from_target_dir, target_dir)
                self.clear_collected_snapshot_files(airphone_connection, files_from_target_dir)
            except Exception as e:
                logging.debug(e)
                raise e

    def clear_collected_snapshot_files(self, airphone_connection: ssh, target_dir_files: Union[list, str]):
        logging.debug(f"Removing all downloaded files from {self.airphone_script_dir}")
        if isinstance(target_dir_files, str):
            target_dir_files = [target_dir_files]
        for path_file in target_dir_files:
            airphone_connection.execute(f"rm -rf {path_file}")
            logging.debug(f"{path_file} was removed")

    @staticmethod
    def _get_airphone_vm_details(airphone_details: dict) -> dict:
        if "path_to_script" in airphone_details:
            airphone_details.pop("path_to_script")
        if "timeout" in airphone_details:
            airphone_details.pop("timeout")
        return airphone_details

    @staticmethod
    def _get_airphone_script_path(airphone_details: dict) -> str:
        path_to_script = airphone_details.get("path_to_script", "/opt/iphy/latest/sosReport_ASIL/sosReport_ASIL.sh")
        return path_to_script
